  "광고주가 등록한 공개 모집 캠페인을 노출 전에 승인/거절합니다. 한 줄에 브랜드·단가·예산·모집·기간·담당자가 모두 보이며, 설명과 지원 조건은 '상세'를 눌러 확인합니다.": "Approves/rejects the public recruitment campaign registered by the advertiser before exposure. The brand, unit price, budget, recruitment, period, and person in charge are all displayed in one line, and the explanation and support conditions can be confirmed by clicking 'Details'.",
  "광고주가 비즈니스 회원가입을 완료하면 이 곳에 표시됩니다.": "Once the advertiser completes business membership registration, it will be displayed here.",
