  "구독료 환불 규정:": "Subscription fee refund policy:",
  "구독을 시작하면 영상 업로드 · 콘텐츠 업로드 등 스탠다드 기능과 함께 협업 타임라인 AI 어시스턴트가 즉시 활성화됩니다. 디엠 자동화는 프로 플랜에서 이용할 수 있습니다.": "When you start subscribing, standard features such as video upload and content upload, as well as the collaborative timeline AI assistant are immediately activated. DM automation is available in the Pro plan.",
  "구독을 시작하면 영상 업로드 · 콘텐츠 업로드 등 스탠다드 기능과 협업 타임라인 AI 어시스턴트, 인스타그램 디엠 자동화가 즉시 활성화됩니다.": "When you start subscribing, standard features such as video upload and content upload, collaboration timeline AI assistant, and Instagram DM automation are immediately activated.",
