  "등록하시면 담당자 승인 후 캠페인 협업 목록에 올라갑니다.": "If you register, you will be placed on the campaign collaboration list after approval by the person in charge.",
  "등록하시면 담당자가 아래 조건으로 후보를 찾아 리스트업해 드립니다. 보시고 마음에 드는 후보만 남기면 됩니다.": "If you register, the person in charge will find and list candidates based on the conditions below. All you have to do is take a look and leave only the candidates you like.",
  "디엠 자동화": "DM automation",
  "디엠 자동화는 프로 플랜 전용 기능이에요.": "DM Automation is a Pro Plan exclusive feature.",
  "디엠 자동화는 프로 플랜 전용 기능입니다": "DM automation is a feature exclusive to the Pro plan.",
  "디엠 자동화는 프로 플랜(월 18,700원) 전용 기능이에요. 멤버십에서 프로 플랜을 구독하면 바로 사용할 수 있어요.": "DM automation is a feature exclusive to the Pro Plan (18,700 won per month). If you subscribe to the Pro plan in Membership, you can use it right away.",
  "디자인 & 블록": "Design & Blocks",
  "또는": "OR",
  "라이브 고객": "Live Customers",
  "라이브 데이터 로딩 중...": "Loading live data...",
  "라이브 방송 및 관련 서비스는 회원의 네트워크 환경, 이동통신사업자의 상태 등에 따라 지연되거나 제한될 수 있으며, 회사는 이로 인해 발생하는 불이익에 대해 고의 또는 중과실이 없는 한 책임을 지지 않습니다.": "Live broadcasts and related services may be delayed or restricted depending on the member's network environment, the status of the mobile communication service provider, etc., and the company is not responsible for any disadvantages resulting from this unless there is intent or gross negligence.",
  "라이브 방송 송출 이력이 1회 이상 있거나 유료 기능을 이용한 내역이 있는 경우, 해당 월의 구독료는 환불되지 않습니다.": "If there is a history of transmitting live broadcasts more than once or if there is a history of using paid functions, the subscription fee for that month will not be refunded.",
  "라이브 방송 송출 인프라 및 클라우드 서버 운영": "Live broadcast transmission infrastructure and cloud server operation",
  "라이브 방송 송출, 방송 알림톡 발송, 인스타그램 자동 DM 전송, 장바구니 및 주문 내역 관리, 일괄 결제 처리": "Live broadcast transmission, broadcast notification message transmission, Instagram automatic DM transmission, shopping cart and order history management, batch payment processing",
  "라이브 방송 중": "Live broadcasting",
  "라이브 시작 알림톡 발송 대상": "To whom the live start notification message will be sent",
  "라이브 커머스 방송 기능 등 멤버십 전용 기능을 이용하기 위해 유료 정기 구독을 체결한 회원을 의미합니다.": "This refers to a member who has signed a paid subscription to use membership-only functions such as live commerce broadcasting functions.",
  "라이브 커머스 방송 페이지에서 알림 신청한 고객이 여기에 표시됩니다.": "Customers who applied for notifications on the live commerce broadcast page will be displayed here.",
