  "메가": "Mega",
  "메가 한 명으로 화제를 만들고 마이크로·나노로 후속 반응을 채우는 구성이 가장 흔합니다. 배분액은 각 규모의 최소 단가 기준이고, 실제 금액은 담당자가 후보를 확정할 때 정해집니다.": "The most common configuration is to create a topic with one mega person and fill in the follow-up response with micro and nano. The distribution amount is based on the minimum unit price of each size, and the actual amount is determined when the person in charge confirms the candidate.",
  "메모": "Memo",
