  "메시지를 입력하세요...": "Please enter your message...",
  "메타 연동": "Meta integration",
  "메타 연동 확인": "Check meta linkage",
  "메타 최근 게시물 목록에서 밀려나 아직 맞추지 못했습니다.": "I haven't been able to guess it yet because it was pushed out of the meta's recent posts list.",
  "메타에서 확인된 지표를 보관 중입니다.": "The indicators confirmed in the meta are being stored.",
  "멤버십": "Membership",
  "멤버십 · 캠페인 마진 · AI 사용 순수익": "Membership · Campaign Margin · AI Use Net Profit",
  "멤버십 구독 및 정산 시 (셀러)": "When subscribing and settling membership (seller)",
  "멤버십 구독과 변경은 PICKS Folio 웹사이트에서 관리할 수 있어요. 웹에서 가입한 멤버십은 앱에서도 그대로 이용됩니다.": "Membership subscriptions and changes can be managed on the PICKS Folio website. Membership signed up on the web can also be used in the app.",
  "멤버십 구독료, 캠페인 마진(브랜드 제시가 − 인플루언서 단가), AI 사용 순수익을 나눠 봅니다. 아래 정산 콘솔에서 인플루언서 지급 예약과 완료 처리를 합니다.": "Divide the membership subscription fee, campaign margin (brand price − influencer unit price), and net revenue from AI use. Influencer payment reservations and completion are processed in the settlement console below.",
  "멤버십 구독을 해지하시겠어요? 해지 후에는 멤버십 전용 기능을 이용할 수 없습니다.": "Do you want to cancel your membership subscription? After cancellation, you will not be able to use membership-only features.",
  "멤버십 변경에 실패했습니다. 잠시 후 다시 시도해 주세요.": "Membership change failed. Please try again later.",
  "멤버십 순수익": "Membership Net Profit",
  "멤버십 안내": "Membership Information",
  "멤버십 플랜": "Membership",
  "멤버십 플랜 보기": "View membership plan",
  "멤버십 플랜에서 구독 시작하기": "Start Subscription with Membership Plan",
  "멤버십 회원(셀러):": "Membership Member (Seller):",
  "멤버십 회원(셀러)은 등록한 결제 수단(신용/체크카드, 카카오페이 등)을 통해 매월 자동으로 구독료를 지불하며, 해지 전까지 서비스 이용 기간은 자동 갱신됩니다.": "Membership members (sellers) automatically pay the subscription fee every month through the registered payment method (credit/check card, Kakao Pay, etc.), and the service period is automatically renewed until cancellation.",
  "멤버십 회원(셀러)은 언제든지 서비스 내 구독 관리 기능을 통해 정기 구독 해지를 신청할 수 있습니다. 해지 시 다음 결제일부터 추가 결제가 이루어지지 않으며, 남은 구독 기간 동안은 라이브 커머스 기능을 정상적으로 이용할 수 있습니다.": "Membership members (sellers) can apply to cancel their regular subscription at any time through the subscription management function within the service. Upon cancellation, no additional payment will be made from the next payment date, and you can use the live commerce function normally for the remaining subscription period.",
  "멤버십 회원(셀러)의 라이브 방송을 시청하고, 방송 중 소개되는 상품을 장바구니에 담아 결제하는 고객을 의미합니다.": "This refers to a customer who watches the live broadcast of a membership member (seller), places the products introduced during the broadcast in their shopping cart, and pays for them.",
  "멤버십 회원(셀러)이 라이브 커머스 기능을 이용하기 위해 월 단위로 구독료를 결제하고 해지 전까지 자동 갱신되는 이용 방식을 말합니다.": "Membership Member (seller) pays a subscription fee on a monthly basis to use the live commerce function and automatically renews it until cancellation.",
  "멤버십 회원(셀러)이 송출한 라이브 방송 및 이를 녹화한 다시보기 영상의 저작권, 영상에 등장하는 자의 초상권은 원칙적으로 셀러에게 귀속되며, 셀러는 회사에 대해 서비스의 운영·홍보·개선, 관련 서비스 연동, 기술적 전송에 필요한 범위에서 해당 영상을 사용, 복제, 전시, 전송, 편집, 2차적 저작물 작성할 수 있는 비독점적이고 무상의 라이선스를 부여합니다.": "The copyright of the live broadcast transmitted by membership members (sellers) and the replay video recorded thereof, as well as the portrait rights of the person appearing in the video, belong to the seller in principle, and the seller grants the company a non-exclusive and free license to use, reproduce, display, transmit, edit, and create secondary works of the video to the extent necessary for the operation, promotion, and improvement of the service, linkage with related services, and technical transmission.",
  "멤버십 회원(셀러)이 월 구독 기간 중 청약철회 또는 해지를 신청하는 경우, 이미 결제가 완료된 해당 월의 잔여 기간(잔여일) 동안 라이브 커머스 등 멤버십 전용 기능을 종료일까지 정상적으로 계속 이용할 수 있도록 이용 권리가 보장됩니다.": "If a membership member (seller) applies for cancellation or cancellation during the monthly subscription period, the right to use membership-only functions such as live commerce as normal until the end date is guaranteed for the remaining period (remaining days) of the month for which payment has already been completed.",
  "멤버십에 가입하면 이 기능을 사용할 수 있어요. 웹에서 가입한 멤버십은 앱에서도 그대로 이용됩니다.": "You can use this feature by signing up for membership. Membership signed up on the web can also be used in the app.",
  "멤버십은 이번달 기준, 캠페인·AI는 누적": "Membership is as of this month, campaigns and AI are cumulative",
  "멤버십은 활성 구독자 × 월 구독료입니다. 캠페인 순수익은 브랜드 제시가와 인플루언서 단가가 모두 입력된 후보만 집계합니다": "Membership is active subscribers × monthly subscription fee. Campaign net revenue is calculated only for candidates for whom both the brand price and the influencer unit price are entered.",
