  "상품·이미지·영상": "Product/Image/Video",
  "상품·이미지·영상·텍스트와 프로필·커버·버튼을 한 곳에서 관리하고, 개인페이지에 보이는 그대로 미리볼 수 있어요.": "Manage products, images, videos, text, profile, cover, and buttons in one place with real-time preview.",
  "상품명": "Product Name",
  "상품명 검색...": "Product name search...",
  "상품의 매매계약은 시청자(구매자)가 멤버십 회원(셀러)이 제시한 상품의 판매 조건에 응하여 청약의 의사표시를 하고, 이에 대하여 셀러가 승낙의 의사표시를 함으로써 체결됩니다. 구매하려는 상품의 내용과 거래 조건을 확인하지 않고 구매함으로써 발생하는 손실과 손해는 시청자(구매자) 본인에게 귀속됩니다.": "A product sales contract is concluded when the viewer (buyer) expresses his/her intention to subscribe in response to the sales conditions of the product presented by the membership member (seller), and the seller expresses his/her intention to accept this. Losses and damages incurred by purchasing the product without checking the contents and transaction terms are the responsibility of the viewer (buyer).",
  "상품의 배송과 관련된 일체의 책임은 판매 주체인 멤버십 회원(셀러)에게 있으며, 회사는 통신판매중개자로서 배송에 관여하지 않습니다.": "All responsibility related to the delivery of the product lies with the membership member (seller) who is the seller, and the company is not involved in delivery as a mail order intermediary.",
  "상품의 취소·반품·교환과 관련된 일체의 책임은 판매 주체인 멤버십 회원(셀러)에게 있으며, 구체적 처리 기준은 「전자상거래 등에서의 소비자보호에 관한 법률」 등 관련 법령과 셀러가 고지한 판매 정책을 따릅니다.": "All responsibility related to cancellation, return, and exchange of products lies with the membership member (seller) who is the seller, and specific processing standards follow related laws such as the Act on Consumer Protection in Electronic Commerce, etc. and the sales policy notified by the seller.",
  "상호명": "Company Name",
