  "생략": "Skipped",
  "서버 연결이 설정되지 않아 카카오 로그인을 사용할 수 없습니다. 아이디/비밀번호로 로그인해 주세요.": "Kakao Login cannot be used because the server connection has not been established. Please log in with your ID/password.",
  "서버 오류가 발생했습니다:": "Server error:",
  "서버 오류가 발생했습니다.": "Server error occurred.",
  "서버 오류가 발생했습니다. 잠시 후 다시 시도해 주세요.": "A server error occurred. Please try again later.",
  "서버 응답 오류": "Server response error",
  "서버에 연결할 수 없습니다. 네트워크 연결을 확인하거나, 잠시 후 다시 시도해주세요. (콘솔에서 상세 에러를 확인하세요)": "Unable to connect to server. Please check your network connection or try again later. (Check the detailed error in the console)",
  "서비스 시스템, API, 방송 송출 인프라에 대한 비정상적 접근·해킹·역공학·자동화 도구를 이용한 부정 이용 행위": "Illegal use of service systems, APIs, and broadcasting transmission infrastructure using abnormal access, hacking, reverse engineering, and automation tools",
  "서비스 이용 과정에서 자동 수집": "Automatically collected during service use",
  "서비스 이용계약은 서비스를 이용하려는 자가 본 약관 및 개인정보처리방침에 동의하고 회사가 정한 양식에 따라 가입을 신청한 후, 회사가 이를 승낙함으로써 성립합니다.": "The service use agreement is established when the person who wishes to use the service agrees to these terms and conditions and the personal information processing policy, applies for membership in the form set by the company, and the company approves it.",
  "서비스 화면에 게시되는 상품 정보, 광고, 영상, 기타 게시물은 원칙적으로 셀러 또는 작성자 본인에 의해 등록된 것으로, 그 정확성·적시성·적법성·타당성에 대하여 회사는 보증하지 아니합니다.": "Product information, advertisements, videos, and other postings posted on the service screen are, in principle, registered by the seller or the author himself, and the company does not guarantee their accuracy, timeliness, legality, or validity.",
  "서비스 화면에서 링크, 배너 등을 통해 연결된 외부 사이트 또는 제휴업체(이하 \"피연결업체\")와 회원 간에 이루어진 거래에 대해 회사는 개입하지 아니하며 책임을 지지 않습니다.": "The company does not intervene and is not responsible for transactions made between members and external sites or affiliated companies (hereinafter referred to as “connected companies”) connected through links, banners, etc. on the service screen.",
  "서비스가 초기화되지 않았습니다. 잠시 후 다시 시도해주세요.": "The service has not been initialized. Please try again later.",
  "서비스를 우회하여 시청자(구매자)와 셀러 간에 직거래를 유도하거나 결제 시스템 외부에서 대금을 수수하는 행위": "Bypassing the service and inducing direct transactions between viewers (buyers) and sellers or receiving payment outside the payment system",
  "서비스에 가입하여 기본 링크 관리 기능을 이용하는 고객을 의미합니다.": "This refers to a customer who subscribes to the service and uses the basic link management function.",
