  "세후 예상 수령액": "Estimated Net Payout",
  "세후 지급 예상": "Expected payment after tax",
  "셀러는 약속된 배송 일정보다 3일 이상 지연이 예상되는 경우 시청자(구매자)에게 사전에 고지하여야 하며, 이와 관련한 클레임에 대해 성실히 응대해야 합니다.": "If a delay of more than 3 days is expected from the promised delivery schedule, the seller must notify viewers (buyers) in advance and respond faithfully to any claims related to this.",
  "셀러는 회사의 사전 동의 없이 회사에 부여한 위 권리를 제한하는 방식으로 저작권을 제3자에게 양도하거나 처분할 수 없습니다.": "The seller may not transfer or dispose of the copyright to a third party in a way that limits the above rights granted to the company without the prior consent of the company.",
  "셀러의 실시간 방송 송출, 시청자의 실시간 장바구니 담기·일괄 결제, 비즈니스 타임라인 등 멤버십 전용 기능이 포함된 유료 서비스": "Paid service that includes membership-only functions such as seller's real-time broadcast transmission, viewer's real-time addition to shopping cart/bulk payment, and business timeline",
