  "소리도 함께 켜집니다": "The sound also turns on.",
  "소비자분쟁조정위원회, 전자거래분쟁조정위원회, 공정거래위원회, 지방자치단체 등 관련 기관이 요청하는 경우 회사는 분쟁 해결에 필요한 범위에서 셀러의 상호, 대표자 성명, 주소, 전화번호, 이메일 주소 등을 제공하여 협조할 수 있습니다.": "When requested by related organizations such as the Consumer Dispute Mediation Committee, Electronic Commerce Dispute Mediation Committee, Fair Trade Commission, and local governments, the company may cooperate by providing the seller's name, representative name, address, phone number, email address, etc. to the extent necessary to resolve the dispute.",
