  "수락하는 순간 담당자가 조건과 일정을 정리해 진행을 맡고, 상황은": "The moment you accept, the person in charge will organize the conditions and schedule and take charge of the process.",
  "수락하면 이 조건으로 광고 계약이 시작되고, 일정에 맞춰 대본과 영상을 올리게 됩니다. 진행하시겠습니까?": "If accepted, the advertising contract will begin under these conditions, and the script and video will be uploaded according to the schedule. Do you want to proceed?",
  "수락하면 인플루언서에게 선정 안내가 가고, 픽스폴리오 담당자가 중간에서 조건과 일정을 정리해 진행합니다.": "If accepted, the influencer will be notified of selection, and a Pixfolio representative will organize the conditions and schedule and proceed with the selection.",
