  "승인된 제안 총액": "Total Proposals Approved",
  "승인된 제안만 수익으로 집계됩니다": "Only approved suggestions will be counted as revenue",
  "승인된 캠페인은 캠페인 협업 목록에 올라갑니다.": "Approved campaigns will be added to the campaign collaboration list.",
  "승인된 캠페인을 골라 지원자와 등록 인플루언서 풀을 함께 검토하고, 브랜드에 제안할 후보 명단을 만듭니다. 후보마다 인플루언서 단가와 브랜드 제시가를 함께 입력하면 그 차액이 우리 수익으로 집계됩니다.": "Pick approved campaigns, review the pool of applicants and registered influencers, and create a shortlist to pitch to brands. If we enter the influencer unit price and the brand price for each candidate, the difference is calculated as our profit.",
  "승인된 캠페인을 먼저 선택해 주세요.": "Please select an approved campaign first.",
  "승인됨": "Approved",
  "승인하면 다음 단계가 열립니다. 전달하지 않은 브랜드 의견이 남아 있으면 먼저 정리해 주세요.": "Once approved, the next step will open. If you have any undelivered brand opinions, please sort them out first.",
