  "신용·체크카드로 첫 달을 결제하고 가입일 기준 매월 자동결제됩니다. 카드 정보는 저장되지 않고 결제사(나이스정보통신)로만 전달됩니다.": "Pay for the first month with a credit/debit card, and automatic payment is made every month based on the date of subscription. Card information is not stored and is only sent to the payment company (Nice Information & Communication).",
