  "인사이트": "Insight",
  "인사이트 계산 근거": "Insight calculation basis",
  "인사이트 점수는 조회율·반응률·최근 릴스 동향을 합친 값입니다. 팔로워 규모와 무관하게 콘텐츠 성과만 봅니다.": "The insight score is a combination of view rate, response rate, and recent release trends. We only look at content performance, regardless of follower size.",
  "인사이트 좋은 순": "Good insight",
  "인사이트 집계 전": "Before aggregating insights",
  "인사이트는 인플루언서 채널을 Meta·YouTube 등 플랫폼에 연동해 받아옵니다. 인플루언서가 직접 적은 수치는 근거로 쓰지 않기 때문에, 연동 전에는 위 칸이 비어 있습니다.": "Insight is received by linking influencer channels to platforms such as Meta and YouTube. Since the figures directly written by the influencer are not used as a basis, the above field is empty before linking.",
  "인스타": "Insta",
  "인스타 피드 동기화": "Insta Feed Sync",
  "인스타 피드 동기화,": "Insta feed sync,",
  "인스타그램": "Instagram",
  "인스타그램 계정 연동": "Link to Instagram account",
  "인스타그램 계정 연동을 해제할까요? 자동화는 보관되지만 DM 발송이 중단됩니다.": "Would you like to unlink your Instagram account? Your automations will be kept, but direct mail sending will stop.",
  "인스타그램 계정 연동하기": "Connect Instagram Account",
  "인스타그램 계정을 등록해 두시면 브랜드 캠페인 후보 명단에 올라갈 확률이 높아집니다.": "Registering an Instagram account increases your chances of being shortlisted for a brand campaign.",
  "인스타그램 계정을 연동하고": "Link your Instagram account and",
  "인스타그램 계정이 연동되었습니다! 🎉": "Your Instagram account has been linked! 🎉",
