  "인스타그램 연동 완료": "Instagram linking completed",
  "인스타그램 연동으로 채널 정보가 연동됩니다. 유튜브나 틱톡은 필요 시 선택사항으로 추가 입력해 주세요.": "Channel information is linked to Instagram. Please add YouTube or TikTok as optional if necessary.",
  "인스타그램 연동이 만료되어 자동 DM 이 발송되지 않습니다.": "The Instagram link has expired, so automatic DMs are not sent.",
  "인스타그램 자동화로 팔로워를 고객으로 전환해보세요.": "Convert your followers into customers with Instagram automation.",
  "인스타그램 포스팅이 즉시 페이지에 반영됩니다.": "Instagram postings are immediately reflected on the page.",
  "인스타그램 프로필 (선택)": "Instagram profile (optional)",
  "인스타그램 피드를 실시간으로 불러오고,": "Loads the Instagram feed in real time,",
  "인스타그램 피드와 동일한 경험을 제공합니다. 클릭 시 상품 정보가 하단에서 스윽 올라옵니다.": "Seamless Instagram-like feed. Clicking brings product info sliding up.",
  "인스타그램 피드와 상품 정보를 하나로": "Instagram feed & products all in one",
  "인스타그램에 게시물을 올린 뒤 다시 확인해주세요.": "Please check again after posting on Instagram.",
  "인스타그램에 게시물이 있는지 확인해주세요.": "Please check if there are any posts on Instagram.",
  "인스타그램은 연동된 계정에서 정보를 확인합니다. 유튜브나 틱톡 등 추가 채널이 있다면 선택사항으로 입력하세요.": "Instagram checks information from the linked account. If you have additional channels such as YouTube or TikTok, enter them as optional.",
  "인앱 브라우저 제약으로 실패할 수 있어요. 외부 브라우저에서 열면 대부분 해결돼요.": "It may fail due to in-app browser restrictions. Most problems are resolved by opening in an external browser.",
