  "인플루언서가 제안을 수락하면 여기에 일정이 표시됩니다.": "If the influencer accepts your offer, your schedule will appear here.",
  "인플루언서가 제안을 수락하면 여기에 협업 건들이 표시됩니다.": "If the influencer accepts the offer, collaboration items will be displayed here.",
  "인플루언서가 제출하면 이 화면에서 장면·시점별로 의견을 남길 수 있습니다.": "When an influencer submits, you can leave comments by scene and viewpoint on this screen.",
  "인플루언서가 제출한 대본과 영상을 여기서 바로 검수합니다.": "Scripts and videos submitted by influencers are reviewed here.",
  "인플루언서가 지원 여부를 정할 때 가장 먼저 읽는 내용입니다. 제품의 특징과 꼭 강조하고 싶은 점을 두세 줄로 적어 주세요.": "This is the first thing an influencer reads when deciding whether to apply. Please write down the features of the product and what you want to emphasize in two or three lines.",
  "인플루언서가 촬영할 때 지켜야 할 것을 적어 주세요. 담당자가 이 내용을 정리해 전달합니다. 작성 전에는 촬영이 시작되지 않습니다.": "Please write down what influencers must follow when filming. The person in charge will organize this information and deliver it to you. Filming does not begin until writing.",
  "인플루언서가 확정되고 업로드가 끝나면 지표가 이 화면에 쌓입니다.": "After the influencer is confirmed and the upload is completed, indicators are accumulated on this screen.",
  "인플루언서별 누적 거래액": "Cumulative transaction amount by influencer",
  "인플루언서별 누적 거래액 TOP": "TOP cumulative transaction amount by influencer",
  "인플루언서별 정산 현황": "Settlement status by influencer",
  "인플루언서별로 한 줄씩 표시됩니다. 이름을 누르면 그 인플루언서에게 공유된 가이드라인과 단계별 진행을 확인할 수 있습니다. 단계 승인과 마감 관리는 담당자가 진행하고, 의견은 담당자에게 전달됩니다.": "One line is displayed for each influencer. If you click on the name, you can check the guidelines and step-by-step progress shared with that influencer. Stage approval and deadline management are carried out by the person in charge, and opinions are conveyed to the person in charge.",
  "인플루언서에게 바로 전달됩니다": "It will be delivered directly to the influencer",
  "인플루언서에게 보낸 제안 현황을 확인하세요.": "Check the status of proposals sent to the influencer.",
  "인플루언서에게 전달됨": "Delivered to influencer",
  "인플루언서에게 전달했습니다.": "I delivered it to the influencer.",
  "인플루언서에게 제안을 보내면 여기서 현황을 확인할 수 있습니다.": "Send a proposal to an influencer and you can check the status here.",
  "인플루언서와 브랜드는 서로의 방을 볼 수 없습니다. 양쪽 말을 옮기는 것은 담당자입니다.": "Influencers and brands cannot see each other’s rooms. It is the person in charge of moving both pieces.",
  "인플루언서와 비즈니스 계정을 합한 전체 가입 수입니다.": "Total number of sign-ups including influencer and business accounts.",
  "인플루언서와의 협업 메시지를 확인하세요.": "Check the collaboration message with the influencer.",
