  "자동충전은 회원이 언제든지 해지할 수 있으며, 해지 후에는 다음 자동충전부터 결제가 이루어지지 않습니다. 해지 전에 이미 승인된 자동충전 결제 건은 본 조의 크레딧 환불 기준에 따라 취소 또는 환불됩니다.": "Automatic recharge can be canceled by the member at any time, and after cancellation, payment will not be made from the next automatic recharge. Automatic recharge payments that have already been approved prior to termination will be canceled or refunded in accordance with the credit refund standards in this Article.",
