  "잔여일에 대한 환불을 포함한 전액 환불은 위 ‘구독료 환불 규정’에 따라 결제 후 7일 이내 미사용에 해당하는 청약철회의 경우에 한하여 처리됩니다.": "Full refunds, including refunds for remaining days, will be processed only in cases of cancellation of subscription for unused subscription within 7 days of payment in accordance with the ‘Subscription Fee Refund Policy’ above.",
