  "줄 왼쪽 화살표를 누르면 브랜드 픽 · 제안 단계와 마진 계산 근거를 볼 수 있습니다. 진행 단계는 지원자 수 → 리스트업 후보 → 브랜드가 진행 요청한 후보 → 담당자가 조건을 보낸 후보 → 수락한 후보 → 진행 중 협업 순입니다. 마진은 브랜드 제시가와 인플루언서 단가가 모두 입력된 수락 후보만 집계합니다.": "line to view the brand pick/suggestion stages and margin calculation basis. The progression steps are as follows: number of applicants → list-up candidates → candidates requested by the brand → candidates to whom the person in charge sent conditions → accepted candidates → collaboration in progress. Margin only counts accepted candidates for which both the brand price and the influencer unit price are entered.",
