  "캠페인 진행 현황을 불러오는 중...": "Loading campaign progress status...",
  "캠페인 협업": "Campaigns",
  "캠페인 협업 목록에 노출 · 인플루언서가 직접 지원": "Exposure to campaign collaboration list · Direct support from influencers",
  "캠페인 협업 목록에 올라가고, 인플루언서가 직접 지원합니다. 광고비 없이 제품만 제공하므로 구성안·콘텐츠 검수 단계가 없고, 가이드를 전달한 뒤 업로드를 확인하는 흐름으로 진행됩니다.": "It is listed on the campaign collaboration list, and the influencer directly applies. Since we only provide products without advertising costs, there is no composition plan or content inspection stage, and the process proceeds by delivering a guide and then confirming the upload.",
  "캠페인 협업 목록에 올라가고, 판매를 함께할 인플루언서가 직접 지원합니다. 광고비 대신 판매 수수료로 정산하며, 콘텐츠 검수와 수수료 정산 단계가 있습니다.": "You will be listed on the campaign collaboration list, and the influencer who will be working with you on sales will apply directly. It is settled with a sales commission instead of an advertising fee, and there are content inspection and commission settlement steps.",
  "캠페인 협업에서 캠페인을 등록하면 진행 이력이 이 화면에 쌓입니다.": "When you register a campaign in Campaign Collaboration, the progress history is accumulated on this screen.",
  "캠페인 협업하기": "Collaborate on campaigns",
  "캠페인 확정까지 남은 시간": "Time remaining until campaign confirmation",
  "캠페인별 배정과 검수": "Assignment and inspection by campaign",
  "캠페인에 선정되었습니다!": "You have been selected!",
  "캠페인을 고르면 후보 풀에서 명단을 만들고, 브랜드가 고른 후보에게 조건을 담아 제안합니다. 제품 협찬형은 지원자만 받으므로 목록에 없습니다.": "When you select a campaign, a list is created from the candidate pool and a proposal is made to the candidate selected by the brand with conditions. The product sponsorship type is not on the list because it only accepts applicants.",
  "캠페인을 눌러 들어가면 인플루언서를 배정할 수 있습니다. 담당자가 없는 캠페인이 위에 옵니다.": "Click on the campaign to enter and assign an influencer. Campaigns without an owner are on top.",
  "캠페인을 등록하고 크리에이터의 지원을 받아보세요.": "Register a campaign and receive support from creators.",
  "캠페인을 마감했습니다.": "The campaign has ended.",
  "캠페인을 불러오는 중...": "Loading campaign...",
  "캠페인을 불러오지 못했습니다.": "The campaign failed to load.",
  "캠페인을 삭제했습니다.": "The campaign has been deleted.",
  "캠페인의 얼굴이 되는 대표 콘텐츠를 만듭니다": "Create representative content that becomes the face of the campaign",
  "캠페인이 관리자 승인 후 공개되고, 담당자가 배정됩니다.": "The campaign will be released after administrator approval, and a person in charge will be assigned.",
  "캠페인이 등록되었습니다. 담당자가 조건에 맞는 인플루언서를 찾아 리스트업해 드립니다.": "The campaign has been registered. The person in charge will find influencers that meet the conditions and list them.",
  "캠페인이 등록되었습니다. 승인 후 캠페인 협업 목록에 올라가고, 지원자가 모이면 그 중에서 고르실 수 있습니다.": "The campaign has been registered. After approval, you will be placed on the campaign collaboration list, and when applicants gather, you can choose from them.",
