  "크레딧": "Credit",
  "크레딧 사용 경로: 협업 타임라인 AI에서 Claude 선택 후 질문 시 답변별 사용량만큼 차감": "Credit usage path: After selecting Claude in the collaboration timeline AI, when asking a question, the amount used for each answer is deducted.",
  "크레딧 소진 시 클로드 관리 화면에서 추가 충전": "When credit is exhausted, additional charge is made on the clode management screen.",
  "크레딧 적립에 실패했습니다.": "Credit accumulation failed.",
  "크레딧 충전": "Credit recharge",
  "크레딧 충전 · 단건 결제": "Credit recharge · Single payment",
  "크레딧 충전 경로: 이 플랜 화면에서 첫 결제 후 협업 타임라인 AI의 클로드 관리 화면에서 추가 충전": "Credit recharge path: After making the first payment on this plan screen, additional recharge on the cloud management screen of Collaboration Timeline AI",
  "크레딧을 모두 사용했어요. 충전하면 계속 이용할 수 있습니다.": "I used all my credits. You can continue using it by charging it.",
  "크레딧이 충전됩니다.": "Credit will be charged.",
  "크리에이터 캠페인 목록에 더 이상 노출되지 않습니다. 계속 모집하려면 수정에서 희망 업로드 시작일을 늦춰 주세요.": "It will no longer appear in the creator campaign list. If you would like to continue recruiting, please delay your desired upload start date in Edit.",
  "클라우드 동기화 완료!": "Cloud synchronization complete!",
  "클로드 크레딧 관리": "Cloth credit management",
  "클로드 플랜": "Claude Plan",
  "클로드 플랜 · 🤖 Claude": "Claude Plan · 🤖 Claude",
  "클로드 플랜 · 🤖 Claude (별도)": "Claude Plan · 🤖 Claude (separately)",
  "클로드 플랜 시작": "Start Clod Plan",
  "클로드 플랜 크레딧은 협업 타임라인 AI에서 Claude 모델을 이용하기 위한 선불 디지털 이용권이며, 현금으로 환급되거나 서비스 외부에서 양도·전환될 수 없습니다.": "Claude Plan Credit is a prepaid digital voucher to use the Claude model in Collaborative Timeline AI, and cannot be refunded for cash or transferred or converted outside of the service.",
  "클로드 플랜과 크레딧 충전은 네이버페이, 페이코, 토스페이, 카카오페이 등 간편결제를 지원하지 않습니다.": "Clauded plan and credit recharge do not support simple payments such as Naver Pay, Payco, Tos Pay, and Kakao Pay.",
  "클로드 플랜과 크레딧 충전은 PICKS Folio 웹사이트에서 이용할 수 있어요. 웹에서 시작하면 앱에서도 클로드를 그대로 사용할 수 있습니다.": "Cload plan and credit recharge are available on the PICKS Folio website. If you start on the web, you can use Claude in the app as well.",
  "클로드 플랜은 네이버페이, 페이코, 토스페이, 카카오페이 등 간편결제를 지원하지 않습니다.": "Clauded Plan does not support simple payments such as Naver Pay, Payco, Tos Pay, and Kakao Pay.",
  "클로드 플랜은 멤버십과 별도로 결제되는 선불 크레딧입니다. 크레딧을 모두 사용하면 이 화면에서 수동으로 충전할 수 있습니다.": "Clauded Plan is a prepaid credit paid separately from membership. Once you've used up all your credits, you can top them up manually from this screen.",
  "클릭 TOP 3": "Top 3 Clicks",
