  "타인의 정보를 도용하거나 허위 정보를 기재한 경우": "In case of stealing another person's information or providing false information",
  "타인의 지식재산권, 초상권, 명예, 개인정보 등을 침해하거나 음란·폭력·차별·혐오 등 공서양속에 반하는 콘텐츠를 등록하거나 방송하는 행위": "Acts of registering or broadcasting content that violates other people's intellectual property rights, portrait rights, reputation, personal information, etc., or that are against public order and morals, such as obscenity, violence, discrimination, hatred, etc.",
