  "표시 형식": "Display format",
  "표시된 금액은 인플루언서에게 지급되는 금액입니다. 원천징수(3.3%)는 지급 시 차감되며, 세금계산서는 지급 완료 후 발행됩니다.": "The amount shown is the amount paid to the influencer. Withholding tax (3.3%) will be deducted upon payment, and a tax invoice will be issued after payment is completed.",
  "표시된 모든 금액은 부가세(VAT 10%)가 포함된 금액": "All prices shown include value-added tax (10% VAT)",
  "표시할 정산 내역이 없습니다.": "There are no settlement details to display.",
  "퓨어 화이트": "Pure White",
  "프로": "Pro",
  "프로 플랜": "Pro Plan",
  "프로 플랜 · 🚀 전체 기능": "Pro Plan · 🚀 Full Features",
  "프로 플랜 🚀": "Pro Plan 🚀",
  "프로 플랜(월 18,700원 · 부가세 포함)을 구독하면 모든 멤버십 플랜 혜택과 함께 인스타그램 디엠 자동화를 사용할 수 있어요. 구독 전에는 자동화를 저장하거나 자동 DM 을 발송할 수 없습니다.": "If you subscribe to the Pro Plan (18,700 won per month, VAT included), you can use Instagram DM automation along with all membership plan benefits. You cannot save automations or send automated DMs before subscribing.",
  "프로 플랜에 가입하면 모든 멤버십 혜택과 함께 인스타그램 디엠 자동화를 사용할 수 있어요. 가입은 PICKS Folio 웹사이트에서 할 수 있으며, 웹에서 가입하면 앱에서도 그대로 이용됩니다.": "If you sign up for the Pro Plan, you can use Instagram DM automation along with all membership benefits. You can sign up on the PICKS Folio website, and if you sign up on the web, you can use it in the app as well.",
  "프로 플랜으로 업그레이드": "Upgrade to Pro Plan",
  "프로 플랜은 스탠다드 · AI 협업 멤버십 혜택을 포함하며, 인스타그램 디엠 자동화는 프로 플랜에서만 이용할 수 있습니다.": "The Pro Plan includes standard and AI collaboration membership benefits, and Instagram DM automation is only available in the Pro Plan.",
  "프로필": "Profile",
