  "허위·과장 광고, 원산지·성능·효능의 오인을 유발하는 표시, 관련 법령이 금지하는 상품의 판매 등 「전자상거래 등에서의 소비자보호에 관한 법률」, 「표시·광고의 공정화에 관한 법률」, 「정보통신망 이용촉진 및 정보보호 등에 관한 법률」 등을 위반하는 행위": "Acts that violate the 「Act on Consumer Protection in Electronic Commerce, etc.」, 「Act on Fair Labeling and Advertising」, 「Act on Promotion of Information and Communications Network Utilization and Information Protection, etc.」, such as false or exaggerated advertising, labeling that causes misunderstanding of the origin, performance, or efficacy, and sale of products prohibited by relevant laws.",
