  "협업이 시작됐습니다. 대본·영상 제출은 아래 진행 화면에서 단계별로 하시면 됩니다.": "Collaboration has begun. You can submit scripts and videos step by step using the progress screen below.",
  "협업이 시작됐습니다. 진행 상황은 아래 협업 현황에서 확인하실 수 있습니다.": "Collaboration has begun. You can check the progress in the collaboration status below.",
