  "회원가입": "Sign Up",
  "회원가입 때 정하는 나만의 링크 이름이에요.": "This is your personal link name that you choose when you sign up.",
  "회원가입 및 로그인 시": "When registering and logging in",
  "회원가입 시 등록한 이름과 전화번호로 아이디를 찾습니다.": "Find ID registered with name & phone number.",
  "회원가입 시 수집한 생년월일/성별 정보를 기반으로 대상이 자동 선정됩니다.": "The target is automatically selected based on the date of birth/gender information collected when signing up.",
  "회원가입 실패": "Signup failed",
  "회원가입 중 오류가 발생했습니다.": "An error occurred during signup.",
  "회원가입에 실패했습니다.": "Your membership registration failed.",
  "회원가입이 완료되었습니다! 로그인해 주세요.": "Signup complete! Please log in.",
  "회원가입하기": "Sign Up",
  "회원관리 및 이용자 식별:": "Membership management and user identification:",
  "회원은 가입 시 허위의 정보를 제공하여서는 아니 되며, 기재한 사항이 변경되었을 경우 지체 없이 최신 정보로 수정하여야 합니다.": "Members must not provide false information when signing up, and if any information has changed, they must update it to the latest information without delay.",
  "회원은 개정된 약관에 동의하지 않을 경우 회원 탈퇴를 할 수 있으며, 변경된 약관의 공지 또는 통지에도 불구하고 이를 확인하지 않아 발생한 피해에 대해서는 회사가 책임을 지지 않습니다.": "Members may withdraw from membership if they do not agree to the revised terms and conditions, and the company is not responsible for any damage resulting from failure to confirm the revised terms and conditions despite notice or notification.",
  "회원은 본 조에 따른 조치에 대해 이의가 있을 경우 회사에 항변할 수 있으며, 회사는 회원의 항변이 정당하다고 인정되는 경우 해당 조치를 철회하거나 조정할 수 있습니다.": "If a member has an objection to an action taken under this Article, he or she may appeal to the company, and the company may withdraw or adjust the action if the member's defense is deemed justified.",
  "회원은 서비스 이용과 관련하여 다음 각 호의 행위를 하여서는 아니 됩니다.": "Members must not engage in any of the following acts in connection with the use of the service.",
  "회원은 접속정보의 도난 또는 제3자의 무단 사용 사실을 인지한 즉시 회사에 통보해야 하며, 회사는 이를 신속하게 처리하기 위해 최선의 노력을 다합니다.": "Members must immediately notify the company upon becoming aware of the theft of access information or unauthorized use by a third party, and the company will do its best to process this promptly.",
  "회원은 클로드 플랜 최초 결제 또는 크레딧 자동충전 결제 후 7일 이내에 해당 결제로 지급된 유상 크레딧을 전혀 사용하지 않은 경우 청약철회를 요청할 수 있으며, 회사는 결제 금액 전액을 환불합니다.": "Members may request cancellation of subscription if they do not use any of the paid credits paid for the payment within 7 days after the initial payment or credit automatic recharge payment for the Claude Plan, and the company will refund the full amount paid.",
  "회원의 계정(이메일, 비밀번호, 소셜 로그인 식별자 등 접속정보)에 대한 관리 책임은 회원에게 있으며, 회원은 어떠한 경우에도 자신의 접속정보를 타인에게 양도하거나 대여할 수 없습니다.": "The member is responsible for managing the member's account (access information such as email, password, social login identifier, etc.), and under no circumstances can the member transfer or rent his or her access information to another person.",
  "회원의 귀책사유로 인한 서비스 이용 장애, 회원이 자신의 접속정보 또는 개인정보를 타인에게 유출·제공함으로써 발생한 피해에 대해 회사는 책임을 지지 않습니다.": "The company is not responsible for any disruption in service use due to reasons attributable to members, or for damage caused by members leaking or providing their access information or personal information to others.",
  "회원이 결제 과정에서 입력한 정보 및 그로 인해 발생한 책임은 전적으로 해당 회원이 부담합니다.": "The information entered by the member during the payment process and any resulting responsibilities are solely borne by the member.",
  "회원이 서비스 외부에서 방송 영상이나 홍보 자료 등을 사용하는 경우 픽스폴리오의 서비스 명칭, 로고 또는 출처 URL을 명시하여 해당 콘텐츠가 픽스폴리오를 통해 제작·유통된 것임을 밝혀야 합니다.": "When members use broadcast videos or promotional materials outside of the service, they must specify Pixfolio's service name, logo, or source URL to reveal that the content was produced and distributed through Pixfolio.",
  "회원이 서비스에 등록한 게시물(텍스트, 이미지, 댓글 등, 영상 제외)의 저작권은 해당 게시물을 작성한 회원 본인에게 귀속되며, 게시물이 타인의 권리를 침해하는 경우 그에 대한 책임은 작성한 회원이 부담합니다.": "The copyright of posts (text, images, comments, etc., excluding videos) registered by members to the service belongs to the member who created the post, and if the post infringes on the rights of others, the member who created the post is responsible for it.",
