  "AI 멤버십에 가입하면 협업 대화 요약, 일정 정리, 답장 초안 작성을 이용할 수 있어요. 멤버십 가입은 PICKS Folio 웹사이트에서 할 수 있으며, 웹에서 가입하면 앱에서도 그대로 사용됩니다.": "If you sign up for AI membership, you can use the ability to summarize collaborative conversations, organize schedules, and draft replies. You can sign up for membership on the PICKS Folio website, and if you sign up on the web, you can use it in the app as well.",
  "AI 사용": "Use AI",
  "AI 사용 순수익": "Net profit using AI",
