  "AI 어시스턴트는 AI 멤버십 전용 기능입니다": "AI Assistant is a feature exclusive to AI membership",
  "AI 어시스턴트는 AI 협업 멤버십(6,900원) 이상에서 이용할 수 있어요. 플랜을 업그레이드하면 바로 사용할 수 있습니다.": "AI Assistant is available with AI Collaboration Membership (KRW 6,900) or higher. Upgrade your plan and you can start using it right away.",
